/* Gold graduation cap seated on rotating globe, only About Details mobile. */
(function(){'use strict';
const cap='<svg viewBox="0 0 120 75" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="anCapGold" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff0a1"/><stop offset=".32" stop-color="#e9b737"/><stop offset=".65" stop-color="#b97908"/><stop offset="1" stop-color="#ffcc51"/></linearGradient></defs><path d="M20 34 60 17 102 34 60 51Z" fill="url(#anCapGold)" stroke="#784307" stroke-width="2.4"/><path d="M38 43v14c12 11 33 11 45 0V43L60 53Z" fill="#a86a0b" stroke="#f4c65d" stroke-width="2"/><path d="M38 54c13 9 32 9 45 0" fill="none" stroke="#ffe17e" stroke-width="3"/><path d="M60 17 102 34v19" fill="none" stroke="#ffe39b" stroke-width="2.5"/><path d="M102 51q-5 9-2 19h8q1-11-6-19Z" fill="url(#anCapGold)" stroke="#935a06" stroke-width="1.5"/><circle cx="102" cy="52" r="4" fill="#ffd66b"/></svg>';
function apply(){if(!matchMedia('(max-width:800px)').matches)return;document.querySelectorAll('#app .an2-graduate-globe .an2-globe-cap').forEach(el=>{if(el.dataset.anGoldCap==='yes')return;el.innerHTML=cap;el.dataset.anGoldCap='yes'})}
let queued=false;function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;apply()})}
document.addEventListener('DOMContentLoaded',()=>{new MutationObserver(schedule).observe(document.getElementById('app'),{childList:true,subtree:true});schedule()},{once:true});window.addEventListener('hashchange',schedule);window.addEventListener('resize',schedule);
})();